import{_ as o,o as s,c as a,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"Dream-RSI：让 Agent 在历史里\\"做梦\\"演练的递归自进化框架","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/dream-rsi.md","filePath":"topics/ai-system-architecture/dream-rsi.md"}'),e={name:"topics/ai-system-architecture/dream-rsi.md"};function n(i,t,d,l,h,g){return s(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="dream-rsi-让-agent-在历史里-做梦-演练的递归自进化框架" tabindex="-1">Dream-RSI：让 Agent 在历史里&quot;做梦&quot;演练的递归自进化框架 <a class="header-anchor" href="#dream-rsi-让-agent-在历史里-做梦-演练的递归自进化框架" aria-label="Permalink to &quot;Dream-RSI：让 Agent 在历史里&quot;做梦&quot;演练的递归自进化框架&quot;">​</a></h1><blockquote><p><strong>来源</strong>：arXiv:2609.14858v1《Dream-RSI: Recursive Self-Improvement through Evolving Worlds》 <strong>作者机构</strong>：¹Google（主导）、²University of Maryland、³Google DeepMind、⁴University of Virginia；通讯作者 <a href="mailto:xidongwu@google.com" target="_blank" rel="noreferrer">xidongwu@google.com</a>、zzhangx@google.com <strong>发布</strong>：2026-09-14（cs.CL）；本次核实 2026-09-18 <strong>核实状态</strong>：✅ 论文真实存在；✅ 全文 36 页已下载并逐数核对；⚠️ 科普转述有 3 处需打折（见第五节） <strong>分类</strong>：AI 系统架构 / 自进化 Agent / 发现系统 <strong>关联</strong>：[[ai-system-architecture/index]]、[[ai-system-architecture/llm-scaling-limits]]、外脑&quot;做梦&quot;任务、[[ai-brain]] 知识网络理念 关键词：Dream-RSI、递归自进化、自进化、回放模拟器、世界模型、AlphaEvolve、探索策略、强化学习、科学发现、智能体、上下文压缩、知识管理、外脑做梦、历史回放、离线试演、Gemini</p></blockquote><hr><h2 id="〇、一句话结论" tabindex="-1">〇、一句话结论 <a class="header-anchor" href="#〇、一句话结论" aria-label="Permalink to &quot;〇、一句话结论&quot;">​</a></h2><p><strong>把跑完的探索历史冻结成&quot;可回放模拟器&quot;，让探索策略先在历史里离线试演打分，再把最优策略派回真实环境。</strong> 核心价值不在&quot;更聪明&quot;，而在<strong>把最贵的反馈环节（真实环境试错）替换成读取已有记录</strong>——零成本回放上千次策略评估。</p><hr><h2 id="一、问题-被浪费的那部分算力" tabindex="-1">一、问题：被浪费的那部分算力 <a class="header-anchor" href="#一、问题-被浪费的那部分算力" aria-label="Permalink to &quot;一、问题：被浪费的那部分算力&quot;">​</a></h2><p>自动发现系统（如 AlphaEvolve）运行时，底层 coding agent 负责写代码，但真正决定成败的是<strong>外层探索策略</strong>：下一步搜哪个方向、并行开几条支线、什么时候停。</p><table tabindex="0"><thead><tr><th>痛点</th><th>具体表现</th></tr></thead><tbody><tr><td>策略是人工写死的</td><td>搜索空间一大就适应不了，在没前途的方向反复烧算力</td></tr><tr><td>在线优化策略太贵</td><td>评价一个<strong>候选方案</strong>只要跑一次评测；评价一个<strong>策略</strong>要看它几十轮里怎么塑造整棵搜索树</td></tr><tr><td>元策略空间极大</td><td>每个版本都在真实环境完整试错 → 开销无法承受</td></tr></tbody></table><p>论文原话：固定策略&quot;fail to adapt as search spaces scale&quot;，而在线策略优化要&quot;navigating vast meta-search spaces under delayed and expensive feedback over long-horizon rollouts&quot;。</p><hr><h2 id="二、核心机制-历史-回放模拟器" tabindex="-1">二、核心机制：历史 = 回放模拟器 <a class="header-anchor" href="#二、核心机制-历史-回放模拟器" aria-label="Permalink to &quot;二、核心机制：历史 = 回放模拟器&quot;">​</a></h2><h3 id="关键洞察" tabindex="-1">关键洞察 <a class="header-anchor" href="#关键洞察" aria-label="Permalink to &quot;关键洞察&quot;">​</a></h3><p>一篇跑完的发现过程，本身就是一棵<strong>结构化的树</strong>：每个节点的起始状态、生成的代码、诊断信息、评测分数全部记录在案。</p><p>因为<strong>节点结果是现成的</strong>，换一个新策略去重走这棵树时——选择不同分支、不同顺序、不同并行分组——<strong>不需要重新运行模型</strong>，就能支撑上千次接近零成本的策略评估。</p><h3 id="与-世界模型-的关键区别-重要" tabindex="-1">与&quot;世界模型&quot;的关键区别（重要） <a class="header-anchor" href="#与-世界模型-的关键区别-重要" aria-label="Permalink to &quot;与&quot;世界模型&quot;的关键区别（重要）&quot;">​</a></h3><p>论文明确划了边界：</p><table tabindex="0"><thead><tr><th></th><th>世界模型 / model-based RL</th><th>Dream-RSI 回放模拟器</th></tr></thead><tbody><tr><td>做什么</td><td><strong>想象</strong>新轨迹</td><td><strong>确定性回放</strong>真实记录</td></tr><tr><td>未探索区域</td><td>可以外推</td><td><strong>一无所知</strong></td></tr><tr><td>可信度</td><td>受模型误差影响</td><td>高（历史里发生过什么就揭示什么）</td></tr></tbody></table><p><strong>在线执行与离线回放共享同一套决策接口</strong>，保证策略在两种环境下表现可比。</p><h3 id="闭环结构" tabindex="-1">闭环结构 <a class="header-anchor" href="#闭环结构" aria-label="Permalink to &quot;闭环结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真实探索 → 产出发现树 → 冻结入&quot;回放世界池&quot;</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                        策略离线试演打分</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                    选最优策略 → 派回真实环境</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                        产出新发现树（扩充池子）</span></span></code></pre></div><ul><li><strong>离线</strong>：低成本试错（只能在历史覆盖范围内重排、调并行、提前剪枝）</li><li><strong>在线</strong>：开拓未知领域（唯一能发现新东西的地方）</li></ul><h3 id="打分机制" tabindex="-1">打分机制 <a class="header-anchor" href="#打分机制" aria-label="Permalink to &quot;打分机制&quot;">​</a></h3><p>底层 agent 之外加一个<strong>轻量编排层</strong>，把探索策略变成可执行代码；一个固定的&quot;策略开发智能体&quot;（大模型）读回放轨迹与得分，分析成败并重写策略代码。回放分数为三项加权：</p><ol><li><strong>＋</strong> 策略揭露子树中<strong>最优解的质量</strong>（核心目标）</li><li><strong>－</strong> 揭露非根节点数 × 成本系数（惩罚真实调用开销）</li><li><strong>＋</strong> 每轮决策平均尝试数 × 并行系数（鼓励把有用尝试打包并行）</li></ol><p><strong>保底机制</strong>：候选集永远包含当前正在用的策略，取平均分最高者 → 新策略在回放分上不会退化。论文原话：<code>Vm* ≥ V0</code>。</p><blockquote><p>⚠️ <strong>注意限定</strong>：这个&quot;不退化&quot;保证<strong>只在&quot;固定历史 H_t 上的平均回放分&quot;层面成立</strong>，<strong>不等于</strong>真实在线性能不退步。科普转述把这一层限定省掉了。</p></blockquote><hr><h2 id="三、实验-三个领域" tabindex="-1">三、实验：三个领域 <a class="header-anchor" href="#三、实验-三个领域" aria-label="Permalink to &quot;三、实验：三个领域&quot;">​</a></h2><p><strong>主对照基线</strong>：Recursive Fixed Exploration（递归固定探索）——除探索策略外所有要素保持一致，以此分离出&quot;策略进化&quot;的真实贡献。</p><h3 id="_1-算法工程-lasso-正则化路径求解器" tabindex="-1">① 算法工程：Lasso 正则化路径求解器 <a class="header-anchor" href="#_1-算法工程-lasso-正则化路径求解器" aria-label="Permalink to &quot;① 算法工程：Lasso 正则化路径求解器&quot;">​</a></h3><p>发现的求解器在<strong>活跃集优化内部做自适应剪枝</strong>：先用强规则筛选和基于<strong>柯西–施瓦茨不等式</strong>的 KKT 剪枝排除特征，只有在无法证明特征无效时才重算精确梯度，配合惰性构造 Gram 矩阵和硬件感知实现。</p><blockquote><p>与以往&quot;按问题维度在算法间切换&quot;的基线不同，它把自适应机制做进了<strong>优化循环内部</strong>，按剪枝可信度动态调整计算量。</p></blockquote><h3 id="_2-gpu-kernel-工程-kernelbench" tabindex="-1">② GPU kernel 工程：KernelBench <a class="header-anchor" href="#_2-gpu-kernel-工程-kernelbench" aria-label="Permalink to &quot;② GPU kernel 工程：KernelBench&quot;">​</a></h3><ul><li>VGG16 / LayerNorm：达到<strong>可比性能</strong>所需代数少 <strong>2.43×</strong> / <strong>1.79×</strong></li><li>ConvDiv / ConvMax：<strong>同等预算</strong>下性能高 <strong>2.09×</strong> / <strong>1.44×</strong></li></ul><h3 id="_3-数学优化" tabindex="-1">③ 数学优化 <a class="header-anchor" href="#_3-数学优化" aria-label="Permalink to &quot;③ 数学优化&quot;">​</a></h3><p>sum-difference、autocorrelation、circle packing：在 <strong>&lt; 1000 次生成</strong>内追平或超越强基线，相对 SimpleTES <strong>节省 &gt; 50× 预算</strong>。</p><hr><h2 id="四、数字逐条核对表-对照论文原文" tabindex="-1">四、数字逐条核对表（对照论文原文） <a class="header-anchor" href="#四、数字逐条核对表-对照论文原文" aria-label="Permalink to &quot;四、数字逐条核对表（对照论文原文）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>科普文的说法</th><th>论文原文</th><th>判定</th></tr></thead><tbody><tr><td>调用次数 550 → 317</td><td><code>using only 317 discovery-agent calls, compared with 550 calls for fixed exploration</code></td><td>✅ 属实</td></tr><tr><td>平均运行时间 3587ms → 2931ms</td><td><code>reduces the average runtime across the six held-out datasets from 3587.1ms to 2931.0ms</code></td><td>✅ 属实</td></tr><tr><td>对比强基线<strong>高达 162 倍</strong>节省</td><td><code>reducing agent calls by up to 162× over SimpleTES and 1.7× over fixed-exploration baselines</code></td><td>⚠️ 见下</td></tr><tr><td>GPU kernel 最多省 2.43 倍</td><td><code>reaches comparable performance with 2.43× and 1.79× fewer generations</code></td><td>✅ 属实</td></tr><tr><td>数学任务不到一千次生成追平</td><td><code>matches or surpasses strong baselines within 1k generations</code></td><td>✅ 属实</td></tr><tr><td>探索强度从 110 降到 50</td><td>Figure 6 (ConvDiv)：<code>reducing the number of evaluated attempts from 110 to 50</code></td><td>✅ 逐字命中</td></tr><tr><td>&quot;把历史写成文字建议反而变差&quot;</td><td>Figure 5：<code>explicit directional guidance consistently underperforms its unguided counterpart</code></td><td>✅ 属实</td></tr><tr><td>新策略&quot;严格不会退化&quot;</td><td><code>no worse than the current policy in average replay score on the fixed history</code></td><td>⚠️ 限定被省略</td></tr></tbody></table><hr><h2 id="五、科普转述的三处失真-需打折" tabindex="-1">五、科普转述的三处失真（需打折） <a class="header-anchor" href="#五、科普转述的三处失真-需打折" aria-label="Permalink to &quot;五、科普转述的三处失真（需打折）&quot;">​</a></h2><h3 id="_1-162-倍-与-1-7-倍是两个完全不同的对照-被揉在一起了" tabindex="-1">① 162 倍 与 1.7 倍是两个完全不同的对照，被揉在一起了 <a class="header-anchor" href="#_1-162-倍-与-1-7-倍是两个完全不同的对照-被揉在一起了" aria-label="Permalink to &quot;① 162 倍 与 1.7 倍是两个完全不同的对照，被揉在一起了&quot;">​</a></h3><ul><li><strong>162×</strong> = 相对 <strong>SimpleTES</strong>（用 51,200 次调用）→ <code>51200 / 317 ≈ 161.5</code></li><li><strong>1.7×</strong> = 相对 <strong>固定探索基线</strong>（550 → 317 = <strong>1.74×</strong>）</li></ul><p>科普文写成&quot;调用次数从 550 锐减至 317，对比强基线系统更是实现了高达 162 倍的节省&quot;——把<strong>同一句话里两个差两个数量级</strong>的对照并列，极易误读成&quot;317 vs 550 就是 162 倍&quot;。<strong>实际是 1.74 倍。</strong></p><p>论文用的是 <strong>&quot;up to&quot;（最多）</strong>，是<strong>上界</strong>不是普遍值。</p><h3 id="_2-运行时间-与-调用次数-是两个维度-被-更-字连成一句" tabindex="-1">② &quot;运行时间&quot;与&quot;调用次数&quot;是两个维度，被&quot;更&quot;字连成一句 <a class="header-anchor" href="#_2-运行时间-与-调用次数-是两个维度-被-更-字连成一句" aria-label="Permalink to &quot;② &quot;运行时间&quot;与&quot;调用次数&quot;是两个维度，被&quot;更&quot;字连成一句&quot;">​</a></h3><ul><li><code>3587ms → 2931ms</code> 是<strong>下游求解器的平均运行时间</strong>（质量指标，只降 18%）</li><li><code>550 → 317</code> 是<strong>发现 agent 的调用次数</strong>（成本指标）</li></ul><p>两者一个是&quot;发现出来的东西好不好用&quot;，一个是&quot;发现过程花了多少算力&quot;。科普文用&quot;不仅…更…&quot;连接，读起来像同一维度的大幅改善。<strong>论文的 &quot;significantly reducing&quot; 主要指后者。</strong></p><h3 id="_3-六个数据集全面超越-sklearn-glmnet-言过其实" tabindex="-1">③ &quot;六个数据集全面超越 sklearn/glmnet&quot;言过其实 <a class="header-anchor" href="#_3-六个数据集全面超越-sklearn-glmnet-言过其实" aria-label="Permalink to &quot;③ &quot;六个数据集全面超越 sklearn/glmnet&quot;言过其实&quot;">​</a></h3><ul><li>论文原话：<code>outperforms standard libraries like sklearn and strong baselines</code>（outperforms <strong>standard libraries like sklearn</strong>）</li><li>并未宣称在<strong>全部六个留出数据集上逐项全面超越</strong>。表格中各列指标方向不同，不宜概括为&quot;全面&quot;。</li></ul><hr><h2 id="六、我的增补分析" tabindex="-1">六、我的增补分析 <a class="header-anchor" href="#六、我的增补分析" aria-label="Permalink to &quot;六、我的增补分析&quot;">​</a></h2><h3 id="_1-这篇论文真正的贡献是-重新定义了什么算反馈" tabindex="-1">1. 这篇论文真正的贡献是&quot;重新定义了什么算反馈&quot; <a class="header-anchor" href="#_1-这篇论文真正的贡献是-重新定义了什么算反馈" aria-label="Permalink to &quot;1. 这篇论文真正的贡献是&quot;重新定义了什么算反馈&quot;&quot;">​</a></h3><p>最贵的不是算力，是**&quot;策略好不好&quot;这个判断本身要等几十轮才知道**。Dream-RSI 的解法是把&quot;在线等待&quot;换成&quot;离线读档&quot;。</p><p>它不碰底层模型、不碰评测器，只优化「<strong>探索控制器</strong>」这一个环节——<strong>切分精准</strong>是它最值得学的工程品味。</p><h3 id="_2-与-世界模型-路线的关系-一次刻意的降级" tabindex="-1">2. 与&quot;世界模型&quot;路线的关系：一次刻意的降级 <a class="header-anchor" href="#_2-与-世界模型-路线的关系-一次刻意的降级" aria-label="Permalink to &quot;2. 与&quot;世界模型&quot;路线的关系：一次刻意的降级&quot;">​</a></h3><p>世界模型追求&quot;能外推的想象&quot;，Dream-RSI 只要&quot;<strong>确定性回放</strong>&quot;。它主动放弃了外推能力，换来<strong>可信度</strong>——回放里没有幻觉，因为没在生成任何新东西。</p><p>代价就是那句硬边界：<strong>回放无法超越历史</strong>。所以必须闭环：离线省钱试错，在线开拓未知。<strong>这不是缺陷，是设计上的自觉。</strong></p><h3 id="_3-最反直觉的一条-其实对知识管理有直接启示" tabindex="-1">3. 最反直觉的一条，其实对知识管理有直接启示 <a class="header-anchor" href="#_3-最反直觉的一条-其实对知识管理有直接启示" aria-label="Permalink to &quot;3. 最反直觉的一条，其实对知识管理有直接启示&quot;">​</a></h3><p><code>explicit directional guidance consistently underperforms</code> ——把历史<strong>提炼成文字建议</strong>塞进提示词，反而变差。论文给的解释是：长周期发现依赖<strong>多线程并行探索</strong>，强语义偏置会&quot;over-constrain the search space and impede diverse exploration&quot;。</p><p><strong>这与本项目 [[ai-brain]] 一条核心设计原则完全同构</strong>：知识库主张&quot;<strong>不过度过滤原始信息</strong>&quot;，原始记录（日记/轨迹）比提炼后的要点更有价值。</p><p>Dream-RSI 从算法侧给了一个实证支持：<strong>原始轨迹是&quot;可复用的模拟器&quot;，而提炼成建议是&quot;一次性的偏置&quot;</strong>。前者能反复推演，后者会锁死搜索空间。</p><p>→ 对&quot;外脑&quot;的启示：<strong>保留原始会话记录 ≈ 保留回放世界池；只留摘要 ≈ 只剩文字建议。</strong></p><h3 id="_4-与-外脑做梦-任务的同构-强关联" tabindex="-1">4. 与&quot;外脑做梦&quot;任务的同构（强关联） <a class="header-anchor" href="#_4-与-外脑做梦-任务的同构-强关联" aria-label="Permalink to &quot;4. 与&quot;外脑做梦&quot;任务的同构（强关联）&quot;">​</a></h3><p>本知识库的定时任务「<strong>外脑做梦</strong>」（每日 07:00 扫描会话库 → 生成待沉淀清单）与 Dream-RSI 是<strong>同一母题的两种实现</strong>：</p><table tabindex="0"><thead><tr><th></th><th>Dream-RSI</th><th>外脑做梦</th></tr></thead><tbody><tr><td>历史来源</td><td>发现树（决策＋结果）</td><td>会话库 state.db</td></tr><tr><td>离线阶段</td><td>在回放模拟器里试演策略</td><td>离线扫描、提炼待沉淀项</td></tr><tr><td>在线阶段</td><td>派回真实探索</td><td>写入 topics/、产生新关联</td></tr><tr><td>共同母题</td><td><strong>把最贵的在线反馈，换成读取已有记录</strong></td><td>同</td></tr></tbody></table><p>Dream-RSI 甚至验证了&quot;<strong>离线阶段不能替代在线阶段</strong>&quot;——这一点对本项目也成立：做梦只产出<strong>清单</strong>，真正的沉淀仍要在真实上下文里做。</p><h3 id="_5-可迁移的判据-什么样的历史才配当-模拟器" tabindex="-1">5. 可迁移的判据：什么样的历史才配当&quot;模拟器&quot; <a class="header-anchor" href="#_5-可迁移的判据-什么样的历史才配当-模拟器" aria-label="Permalink to &quot;5. 可迁移的判据：什么样的历史才配当&quot;模拟器&quot;&quot;">​</a></h3><p>论文隐含了三个前提，对任何想做&quot;历史复用&quot;的系统都是硬门槛：</p><ol><li><strong>结构化记录</strong>——不只要有文本，要有&quot;决策 + 结果&quot;的配对</li><li><strong>决策可重排</strong>——历史能被赋予不同顺序/分组来重走</li><li><strong>接口一致</strong>——离线与在线走同一套决策接口，否则打分不可比</li></ol><p>→ 推广：<strong>任何具备完整轨迹记录的长周期智能体任务</strong>都能用这个思路（论文亦如此宣称）。</p><hr><h2 id="七、局限-论文自陈-我的判断" tabindex="-1">七、局限（论文自陈 + 我的判断） <a class="header-anchor" href="#七、局限-论文自陈-我的判断" aria-label="Permalink to &quot;七、局限（论文自陈 + 我的判断）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>局限</th><th>说明</th></tr></thead><tbody><tr><td>回放质量受限于历史覆盖度</td><td>没见过的东西回放不出来，只能靠在线阶段补</td></tr><tr><td>依赖大模型改写策略代码的能力</td><td>策略开发智能体弱 → 整条链路弱</td></tr><tr><td>跨模型、跨任务族泛化性未验证</td><td>论文只测了三个领域、有限基线</td></tr><tr><td>未解决&quot;非平稳性&quot;</td><td>若环境本身变化，旧历史作模拟器的效度下降（<strong>论文未讨论，我的补充</strong>）</td></tr></tbody></table><p><strong>一句话判断</strong>：机制干净、问题切得准、易复现调试；软肋是<strong>评估质量天花板由历史覆盖度决定</strong>，擅长的场景是&quot;环境稳定 + 轨迹记录完整 + 探索策略是关键瓶颈&quot;。</p><hr><h2 id="八、原文钩子句说明" tabindex="-1">八、原文钩子句说明 <a class="header-anchor" href="#八、原文钩子句说明" aria-label="Permalink to &quot;八、原文钩子句说明&quot;">​</a></h2><p>分享内容结尾&quot;<em>想知道这套&#39;做梦&#39;框架的代码怎么用，或者它在什么场景下不适用吗？</em>&quot;是<strong>原作者/自媒体 CTA（引流话术）</strong>，非本知识库任务。本文第七节已自行回答了&quot;什么场景不适用&quot;。</p><hr><h2 id="九、跨主题关联" tabindex="-1">九、跨主题关联 <a class="header-anchor" href="#九、跨主题关联" aria-label="Permalink to &quot;九、跨主题关联&quot;">​</a></h2><ul><li><strong>[[ai-system-architecture/llm-scaling-limits]]</strong> — 同属&quot;算力怎么花才值&quot;的问题域；Dream-RSI 从探索控制侧给出一个答案</li><li><strong>[[ai-brain]]</strong> — &quot;不过度过滤原始信息&quot;获得算法侧实证支持（见六.3）</li><li><strong>[[ai-system-architecture/weekly-413-analysis]]</strong> — 阮一峰周刊的 AI 系统话题谱系</li><li><strong>社会法/劳动法无关</strong>：注意本文与 <code>topics/law/</code> 无关联，避免误链</li><li><strong>母题</strong>：<strong>&quot;把昂贵的在线反馈换成读取已有记录&quot;</strong> —— 与知识库&quot;沉淀→复用&quot;、cron &quot;先扫描历史再动作&quot;、[[real-estate/district-development-signals]] 的&quot;看客观痕迹而非话术&quot;共享同一母题：<strong>用已发生的事实替代推测</strong></li><li><strong>命名呼应</strong>：本文的 &quot;dreaming&quot; 与本项目定时任务「外脑做梦」形成有趣的同名同构（见六.4）</li></ul><hr><h2 id="十、来源与核实说明" tabindex="-1">十、来源与核实说明 <a class="header-anchor" href="#十、来源与核实说明" aria-label="Permalink to &quot;十、来源与核实说明&quot;">​</a></h2><ol><li><strong>论文来源</strong>：arXiv:2609.14858v1，<code>https://arxiv.org/abs/2609.14858</code>（正文 <code>https://arxiv.org/pdf/2609.14858v1</code>）</li><li><strong>核实方法</strong>：下载 PDF 全文（36 页 / 104,290 字符）→ 抽取文本 → 对科普文中<strong>每一个具体数字</strong>做正则检索 + 上下文人工判读</li><li><strong>核实结论</strong>：论文真实；科普文转述的<strong>所有具体数字都能在原文找到出处</strong>（非编造）；但有 <strong>3 处语境失真</strong>需打折（第五节）</li><li><strong>机构归属</strong>：从 PDF 首页作者脚注确认（¹Google / ²UMD / ³Google DeepMind / ⁴UVA），非推测</li><li><strong>未核实项</strong>：论文的代码/数据是否开源（Comment 字段仅 &quot;12 pages&quot;，未见仓库链接）；PR 数值来源于论文自报，未经第三方复现</li><li><strong>时效提示</strong>：该论文 2026-09-18（核实当日）仍有更新记录，处于活跃修改期，引用请复查版本</li></ol><hr><h2 id="十一、应用评估-这套算法我们能用上吗-2026-09-18-追加" tabindex="-1">十一、应用评估：这套算法<strong>我们</strong>能用上吗（2026-09-18 追加） <a class="header-anchor" href="#十一、应用评估-这套算法我们能用上吗-2026-09-18-追加" aria-label="Permalink to &quot;十一、应用评估：这套算法**我们**能用上吗（2026-09-18 追加）&quot;">​</a></h2><blockquote><p>对照本知识库<strong>真实基础设施</strong>（<code>scripts/dream_scan.py</code>、<code>scripts/auto_link.py</code>、<code>~/.hermes/state.db</code>、<code>scripts/tests/</code>）做的评估，不是泛泛而谈。</p></blockquote><h3 id="_11-1-结论" tabindex="-1">11.1 结论 <a class="header-anchor" href="#_11-1-结论" aria-label="Permalink to &quot;11.1 结论&quot;">​</a></h3><p><strong>机制能用，框架不能直接搬；而且它精准命中了本项目一个此前没意识到的缺陷。</strong></p><h3 id="_11-2-为什么整套搬是负收益-前提不成立" tabindex="-1">11.2 为什么整套搬是负收益（前提不成立） <a class="header-anchor" href="#_11-2-为什么整套搬是负收益-前提不成立" aria-label="Permalink to &quot;11.2 为什么整套搬是负收益（前提不成立）&quot;">​</a></h3><p>Dream-RSI 的立论前提是「<strong>评价一个探索策略的代价极高</strong>」——论文原话：评价单个候选只需跑一次评测，但评价一个策略要观察它在几十轮中如何塑造整棵搜索树。</p><p>本项目的成本结构完全不同：</p><table tabindex="0"><thead><tr><th></th><th>Dream-RSI</th><th>本知识库</th></tr></thead><tbody><tr><td>一次「策略评估」的代价</td><td>数百~数千次 LLM 生成</td><td><strong>读一遍输出，0 次 LLM</strong></td></tr><tr><td>运行频率</td><td>持续在线探索</td><td>dream_scan 每天 1 次（纯 SQLite 查询，零 token）</td></tr><tr><td>可省的成本</td><td>用历史回放代替重跑模型</td><td><strong>无可省</strong>——本来就没在跑模型</td></tr></tbody></table><p>→ <strong>为省算力而造回放模拟器，在这里是多一层抽象、负收益。</strong></p><h3 id="_11-3-但它命中了一个真实缺陷-本项目全在「人工设计的固定规则」上跑" tabindex="-1">11.3 但它命中了一个真实缺陷：本项目全在「人工设计的固定规则」上跑 <a class="header-anchor" href="#_11-3-但它命中了一个真实缺陷-本项目全在「人工设计的固定规则」上跑" aria-label="Permalink to &quot;11.3 但它命中了一个真实缺陷：本项目全在「人工设计的固定规则」上跑&quot;">​</a></h3><p>论文批判的原话是「策略往往是人工设计的固定规则，难以适应复杂多变的搜索空间」。对照 <code>scripts/dream_scan.py</code>：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">USER_LIMIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ASSIST_LIMIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TOTAL_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 900</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">600</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">45000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 第 21 行</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> role </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;assistant&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> and</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(text) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> None</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 第 53 行</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SKIP_MARKERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[IMPORTANT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[System&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第 20 行</span></span></code></pre></div><p><strong>这些常量就是「固定策略」</strong>：900/600/45000、150 字阈值、噪音标记表——都是当初一次拍定的，<strong>从未被任何数据验证过</strong>。</p><p>更关键的是：<code>scripts/tests/run_all.py</code> 的 33 项测试<strong>只验证「没坏」，从不验证「抽得更好」</strong>。 → 于是改这些参数只能靠拍脑袋，<strong>这是本项目自动化链条上唯一「无法自我改进」的位置</strong>。</p><h3 id="_11-4-真正能搬的三件事" tabindex="-1">11.4 真正能搬的三件事 <a class="header-anchor" href="#_11-4-真正能搬的三件事" aria-label="Permalink to &quot;11.4 真正能搬的三件事&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dream-RSI 机制</th><th>本项目对应物</th><th>现状</th><th>可用性</th></tr></thead><tbody><tr><td>把跑完的历史冻结成可回放结构</td><td><code>~/.hermes/state.db</code>（4,789 条消息）</td><td>✅ 已冻结</td><td><strong>现成可用</strong></td></tr><tr><td>策略离线打分 → 选拔</td><td>——</td><td>❌ <strong>完全空白</strong></td><td><strong>唯一真缺口</strong></td></tr><tr><td>候选集永远含当前在用的策略（保底不退化）</td><td>——</td><td>❌</td><td><strong>零成本可搬</strong></td></tr></tbody></table><h3 id="_11-5-建议的最小落地-若要做" tabindex="-1">11.5 建议的最小落地（若要做） <a class="header-anchor" href="#_11-5-建议的最小落地-若要做" aria-label="Permalink to &quot;11.5 建议的最小落地（若要做）&quot;">​</a></h3><p><code>scripts/replay_eval.py</code>：取 N 天历史 → 用「当前参数」与「候选参数」各跑一遍 dream_scan → 对比指标（素材条数 / 用户发言占比 / 截断次数 / 噪音占比）→ <strong>只在多项指标都不差时才替换参数</strong>。</p><p>这就是把论文的<strong>保底机制原样搬过来</strong>：候选集含当前策略，只有平均分更高才换 ⇒ 改参数不可能让产出变差。</p><h3 id="_11-6-诚实打折-什么时候不该做" tabindex="-1">11.6 诚实打折：什么时候<strong>不该</strong>做 <a class="header-anchor" href="#_11-6-诚实打折-什么时候不该做" aria-label="Permalink to &quot;11.6 诚实打折：什么时候**不该**做&quot;">​</a></h3><ol><li><strong>收益上限有限</strong>：它买到的只是「改脚本从拍脑袋变成有依据」，不是「知识库自己变聪明」。</li><li><strong>缺少 ground truth（根本限制）</strong>：论文里「solver 快不快」是客观数字；本项目「哪条素材值得沉淀」是<strong>主观判断</strong>。→ 回放打分能做「<strong>防退化</strong>」，做不了「<strong>找最优</strong>」。</li><li><strong>投入产出比取决于改脚本频率</strong>：一年改不了几次 ⇒ 别做；要让知识库长期自我演进 ⇒ 值得，而且是唯一能挂钩「自我改进」的地方。</li></ol><h3 id="_11-7-反过来最大的收获-论文给本项目一条既有原则做了实验背书" tabindex="-1">11.7 反过来最大的收获：论文给本项目一条既有原则<strong>做了实验背书</strong> <a class="header-anchor" href="#_11-7-反过来最大的收获-论文给本项目一条既有原则做了实验背书" aria-label="Permalink to &quot;11.7 反过来最大的收获：论文给本项目一条既有原则**做了实验背书**&quot;">​</a></h3><p>论文最有价值的实验是<strong>否证</strong>：把历史压成文字建议注入提示词，性能<strong>反而变差</strong>（strong semantic bias 杀死多线程并行探索的多样性）。</p><ul><li>✅ <strong>正面背书</strong>：本项目「日记不过滤原始信息」「保留原始轨迹」的原则是对的——原始轨迹的价值高于它的摘要。</li><li>⚠️ <strong>反向警告</strong>：<strong>不要</strong>为了省 token 把知识库压成一份摘要提示词喂给模型。那正是论文实测会<strong>变差</strong>的做法。</li></ul><hr><p><em>整理日期：2026-09-18 ｜ 数字级核实：已完成 ｜ 打折判断：已标注 ｜ 应用评估（十一节）：2026-09-18 追加</em></p>`,112)])])}const c=o(e,[["render",n]]);export{p as __pageData,c as default};
